<script setup>
import {computed,ref,nextTick,onMounted} from 'vue'
import {request} from './client'
const props=defineProps({policy:Object,googleSession:Boolean});const emit=defineEmits(['back'])
const form=ref({kind:'Student',first_name:'',last_name:'',email:'',phone:'',username:'',country:'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,grade:'',subject:'',organization:'',job:'',backup_name:'',backup_email:'',website:'',qualifications:'',bio:'',privacy_accepted:false})
const extra=computed(()=>form.value.kind==='Student'?['grade']:form.value.kind==='Individual Teacher'?['subject']:['organization','job','backup_name','backup_email'])
const required=computed(()=>['first_name','last_name','email','phone','username','country','timezone',...extra.value])
const label=f=>({first_name:'First name',last_name:'Last name',backup_email:'Recovery contact email',backup_name:'Recovery contact name',job:'Your position',grade:'Grade / study level',subject:'Subject / expertise',organization:'Institute name'}[f]||f.replaceAll('_',' ').replace(/^./,s=>s.toUpperCase()))
const feedback=ref(null),status=ref('')
const token=ref(''),emailCode=ref(''),phoneCode=ref(''),emailOK=ref(false),phoneOK=ref(false),phoneSent=ref(false),password=ref(''),confirmation=ref(''),busy=ref(false),error=ref(''),done=ref(false)
function google(){sessionStorage.setItem('sisu_signup_role',form.value.kind);run(async()=>{const r=await request('portal_policy','google_start',{signup:1});const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='accounts.google.com')throw Error('Google sign-in unavailable');location.assign(u.href)})}
{const role=sessionStorage.getItem('sisu_signup_role');if(['Student','Individual Teacher','Institute'].includes(role))form.value.kind=role}
async function reveal(){await nextTick();feedback.value?.scrollIntoView({behavior:'smooth',block:'center'});feedback.value?.focus({preventScroll:true})}
function invalid(event){error.value='Please complete '+(event.target.getAttribute('aria-label')||'the highlighted required field')+'. '+event.target.validationMessage;reveal()}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';status.value='Working…';try{await fn()}catch(e){error.value=e.message;status.value=''}finally{busy.value=false;reveal()}}
function start(){run(async()=>{const r=await request('registration','self_start',{data:{...form.value,privacy_policy_version:props.policy.privacy_policy_version}});token.value=r.challenge;status.value='Email code requested. Check your inbox and enter it below.'})}
function verify(channel){run(async()=>{await request('registration','self_verify',{token:token.value,channel,code:channel==='email'?emailCode.value:phoneCode.value});if(channel==='email')emailOK.value=true;else phoneOK.value=true;status.value=channel==='email'?'Email verified. Request your phone code next.':'Phone verified. Set your password and save.'})}
function phone(){run(async()=>{await request('registration','self_phone',{token:token.value});phoneSent.value=true;status.value='Phone code requested. Enter the SMS code below.'})}
function save(){run(async()=>{await request('registration','self_complete',{token:token.value,password:password.value,confirmation:confirmation.value});password.value='';confirmation.value='';done.value=true})}
function reset(){token.value='';emailOK.value=false;phoneOK.value=false;phoneSent.value=false;emailCode.value='';phoneCode.value='';password.value='';confirmation.value=''}
onMounted(()=>{if(props.googleSession)run(async()=>{const d=await request('registration','self_google_details',{},'GET');Object.assign(form.value,d);status.value='Google details filled in. Complete the remaining required fields.'})})
</script>
<template><main class="verified-signup"><button type="button" @click="emit('back')">← Back to sign in</button><h1>Create your SISU account</h1><button v-if="!googleSession&&!token&&!done" type="button" class="google-signup" :disabled="busy||!policy.google_available" @click="google"><img :src="'/assets/frappe/icons/social/google.svg'" alt="" width="22" height="22"/> Sign up with Google</button><p v-if="!googleSession&&!policy.google_available" class="google-note">Google signup is not available yet. You can create your account using email below.</p><p v-if="googleSession">Google sign-in completed. Enter that same email below and complete both contact checks. Set a password to also use email/password login.</p><div ref="feedback" tabindex="-1" aria-live="polite" class="signup-feedback"><p v-if="error" role="alert" class="error">{{error}}</p><p v-else-if="status" role="status">{{status}}</p></div><section v-if="done" role="status"><h2>Account created successfully</h2><p>Your details have been saved. Please sign in with your email and password.</p><button class="button primary" @click="emit('back')">Go to sign in</button></section><form v-else @invalid.capture="invalid" @submit.prevent="token?save():start()"><fieldset :disabled="busy||!!token"><label>Account type · Required<select v-model="form.kind"><option>Student</option><option>Individual Teacher</option><option>Institute</option></select></label><div class="signup-grid"><label v-for="field in required" :key="field">{{label(field)}} · Required<input v-model="form[field]" :aria-label="label(field)" :readonly="googleSession&&field==='email'" :type="field.includes('email')?'email':field==='phone'?'tel':'text'" required :maxlength="field.includes('name')?60:254" :placeholder="field==='phone'?'+94761234567':''"/></label><p class="phone-help">Sri Lankan mobile: use +94 and omit the first 0. For example, 0761234567 → +94761234567. Use your authorized test number.</p><label v-for="field in ['website','qualifications','bio']" :key="field">{{label(field)}} · Optional<input v-model="form[field]" :aria-label="label(field)" :readonly="googleSession&&field==='email'" :type="field==='website'?'url':'text'" maxlength="500"/></label></div><label class="consent"><input type="checkbox" v-model="form.privacy_accepted" aria-label="privacy policy acceptance" required/>I accept the <a :href="policy.privacy_policy_url" target="_blank" rel="noopener noreferrer">privacy policy</a>.</label></fieldset><p v-if="form.kind!=='Student'">Your teaching workspace stays locked until your plan payment is verified. Account verification does not grant a provider endorsement badge.</p><button v-if="!token" class="button primary" :disabled="busy||!policy.privacy_policy_url">{{busy?'Sending…':'Send email verification code'}}</button><template v-else><button type="button" :disabled="busy" @click="reset">Edit details / start again</button><section><h2>Email verification {{emailOK?'✓':''}}</h2><label v-if="!emailOK">Six-digit email code<input v-model="emailCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"/></label><button v-if="!emailOK" type="button" :disabled="busy||emailCode.length!==6" @click="verify('email')">Verify email</button></section><section><h2>Phone verification {{phoneOK?'✓':''}}</h2><button v-if="!phoneOK" type="button" :disabled="busy||!emailOK" @click="phone">{{phoneSent?'Resend phone code':'Send phone code'}}</button><label v-if="phoneSent&&!phoneOK">Six-digit phone code<input v-model="phoneCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"/></label><button v-if="phoneSent&&!phoneOK" type="button" :disabled="busy||phoneCode.length!==6" @click="verify('phone')">Verify phone</button></section><label>Password · Required<input v-model="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required/></label><label>Confirm password · Required<input v-model="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="128" required/></label><p>Use 12–128 characters. Both contacts must be verified before saving.</p><button class="button primary" :disabled="busy||!emailOK||!phoneOK||password.length<12||password!==confirmation">Save and create account</button></template></form></main></template>
<style scoped>.verified-signup{max-width:820px;margin:35px auto;padding:28px;background:var(--surface,#fff);border-radius:20px}.verified-signup fieldset{border:0;padding:0}.signup-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.verified-signup label{display:grid;gap:8px;margin:14px 0}.verified-signup input,.verified-signup select{padding:12px;border:1px solid #b9b3c6;border-radius:8px;width:100%;box-sizing:border-box}.verified-signup .consent{display:flex;align-items:center}.consent input{width:auto}.verified-signup button{margin:8px 8px 8px 0;padding:10px 15px}.verified-signup button{min-height:44px;border:1px solid #c4bbd5;border-radius:10px;background:#f5f1fa;color:#38224e;font:600 15px/1.4 system-ui;cursor:pointer}.verified-signup button:disabled{opacity:.55;cursor:not-allowed}.verified-signup button.primary{background:#592b91;color:white;border-color:#592b91}.verified-signup .google-signup{display:flex;align-items:center;justify-content:center;gap:12px;width:100%;padding:14px 20px;background:#fff;border:1px solid #b9b3c6;box-shadow:0 2px 5px #24113712}.google-mark{font:700 22px system-ui;color:#4285f4}.google-note{font-size:14px;color:#64566f}.signup-feedback:focus{outline:2px solid #7652a2;outline-offset:5px}.verified-signup section{margin:22px 0}@media(max-width:600px){.signup-grid{grid-template-columns:1fr}}</style>
